describe("Game of Life - nextGeneration", () => {
  // Simplest cases
  it("should return empty array for empty input -- []", () => {
    expect(nextGeneration([])).toEqual([]);
  });
  it.todo("should kill a single live cell with 0 neighbors -- [(0,0)] -> []");

  // Rule 1: Underpopulation
  it.todo("should kill two adjacent cells each with 1 neighbor (Rule 1) -- [(0,1),(1,1)] -> []");

  // Rule 3: Overpopulation - single cell example for the rule
  // (already covered with full pattern below; we'll keep dedicated tests)

  // Rule 4: Reproduction
  it.todo("should birth a dead cell with exactly 3 live neighbors (Rule 4) -- L-shape [(0,2),(1,2),(0,1)] -> birth (1,1)");

  // Still life: Block
  it.todo("should keep a Block still life unchanged -- [(0,0),(1,0),(0,1),(1,1)] unchanged");

  // Rule 2: Survival - full blinker / T example from spec
  it.todo("should let center cell survive with 3 neighbors (Rule 2) -- T-shape [(0,2),(1,2),(2,2),(1,0)] center (1,1) survives");

  // Rule 3: Overpopulation - full ring example
  it.todo("should kill center cell with 4 neighbors and produce the ring pattern (Rule 3) -- full 3x3 minus center -> 4 corners");

  // Blinker oscillator
  it.todo("should oscillate vertical Blinker to horizontal -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");

  // Negative coordinates
  it.todo("should handle negative coordinates -- Block at [(-1,-1),(0,-1),(-1,0),(0,0)] unchanged");
});

