export type Cell = [number, number];

function key(x: number, y: number): string {
  return `${x},${y}`;
}

export function nextGeneration(cells: Cell[]): Cell[] {
  const live = new Set(cells.map(([x, y]) => key(x, y)));
  const neighborCounts = new Map<string, number>();

  for (const [x, y] of cells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const k = key(x + dx, y + dy);
        neighborCounts.set(k, (neighborCounts.get(k) ?? 0) + 1);
      }
    }
  }

  const next: Cell[] = [];
  for (const [k, count] of neighborCounts) {
    const [xs, ys] = k.split(",");
    const cell: Cell = [Number(xs), Number(ys)];
    if (live.has(k)) {
      if (count === 2 || count === 3) next.push(cell);
    } else {
      if (count === 3) next.push(cell);
    }
  }
  return next;
}

import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - nextGeneration", () => {
  // Simplest cases
  it("should return empty array for empty input -- []", () => {
    expect(nextGeneration([])).toEqual([]);
  });
  it("should kill a single live cell with 0 neighbors -- [(0,0)] -> []", () => {
    expect(nextGeneration([[0, 0]])).toEqual([]);
  });

  // Rule 1: Underpopulation
  it("should kill two adjacent cells each with 1 neighbor (Rule 1) -- [(0,1),(1,1)] -> []", () => {
    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
  });

  // Rule 3: Overpopulation - single cell example for the rule
  // (already covered with full pattern below; we'll keep dedicated tests)

  // Rule 4: Reproduction
  it("should birth a dead cell with exactly 3 live neighbors (Rule 4) -- L-shape [(0,2),(1,2),(0,1)] -> birth (1,1)", () => {
    const result = nextGeneration([[0, 2], [1, 2], [0, 1]]);
    expect(new Set(result.map((c) => c.join(",")))).toEqual(
      new Set([[0, 2], [1, 2], [0, 1], [1, 1]].map((c) => c.join(","))),
    );
  });

  // Still life: Block
  it("should keep a Block still life unchanged -- [(0,0),(1,0),(0,1),(1,1)] unchanged", () => {
    const cells: [number, number][] = [[0, 0], [1, 0], [0, 1], [1, 1]];
    const result = nextGeneration(cells);
    expect(new Set(result.map((c) => c.join(",")))).toEqual(
      new Set(cells.map((c) => c.join(","))),
    );
  });

  // Rule 2: Survival - full blinker / T example from spec
  it.todo("should let center cell survive with 3 neighbors (Rule 2) -- T-shape [(0,2),(1,2),(2,2),(1,0)] center (1,1) survives");

  // Rule 3: Overpopulation - full ring example
  it.todo("should kill center cell with 4 neighbors and produce the ring pattern (Rule 3) -- full 3x3 minus center -> 4 corners");

  // Blinker oscillator
  it.todo("should oscillate vertical Blinker to horizontal -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");

  // Negative coordinates
  it.todo("should handle negative coordinates -- Block at [(-1,-1),(0,-1),(-1,0),(0,0)] unchanged");
});

